function makeCounter(start = 0) {
  let count = start;            // private, lives in the closure
  return {
    increment: () => ++count,
    decrement: () => --count,
    value: () => count
  };
}

const a = makeCounter(10);
const b = makeCounter();
a.increment();
a.increment();
b.decrement();
console.log(a.value()); // 12
console.log(b.value()); // -1
console.log(a.count);   // undefined: no direct access

class User {
  constructor(name) { this.name = name; }
  describe() { return `${this.name} (user)`; }
}
class Admin extends User {
  canDelete() { return true; }
}

const a = new Admin('Riya');
console.log(a.describe());                                  // Riya (user)
console.log(Object.getPrototypeOf(a) === Admin.prototype);  // true
console.log(Object.hasOwn(a, 'describe'));                  // false: inherited

const detached = a.describe;
try { detached(); } catch (e) { console.log(e.constructor.name); } // TypeError
const bound = a.describe.bind(a);
console.log(bound());                                       // Riya (user)

const wait = (ms, value, fail = false) =>
  new Promise((resolve, reject) => setTimeout(() => (fail ? reject(new Error(value)) : resolve(value)), ms));

async function loadDashboard() {
  const started = Date.now();
  const [user, orders] = await Promise.all([wait(100, 'Asha'), wait(100, ['o1', 'o2'])]);
  const [recs] = await Promise.allSettled([wait(20, 'recs down', true)]);
  return {
    user,
    orders,
    recommendations: recs.status === 'fulfilled' ? recs.value : [],
    ms: Math.round((Date.now() - started) / 10) * 10
  };
}

loadDashboard().then(console.log);
// { user: 'Asha', orders: [ 'o1', 'o2' ], recommendations: [], ms: 120 } (approximately)

